<script setup lang="ts">import{onMounted,ref}from"vue";import CpfIcon from"../../components/CpfIcon.vue";import{admApi}from"../../shared/cpfApi";type Row=Record<string,any>;const rows=ref<Row[]>([]),error=ref(""),busy=ref(false);const form=ref({severity:"SEV2",title:"",summary:"",sourceType:"MANUAL",sourceId:"",reason:"운영 장애 등록"});async function api(url:string,opt:RequestInit={}){return admApi(url,opt)}async function load(){try{rows.value=await api('/adm/api/incidents?limit=100')}catch(e){error.value=e instanceof Error?e.message:String(e)}}async function create(){if(!form.value.title.trim())return;busy.value=true;try{await api('/adm/api/incidents',{method:'POST',body:JSON.stringify(form.value)});form.value.title='';form.value.summary='';await load()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}async function transition(r:Row,status:string){const reason=window.prompt(`${status} 처리 사유`);if(!reason)return;await api(`/adm/api/incidents/${r.incidentId}/status`,{method:'POST',body:JSON.stringify({status,reason})});await load()}onMounted(load);</script><template><div class="cpf-page"><div class="cpf-page-heading"><div><p class="eyebrow">INCIDENT LIFECYCLE</p><h2>장애·Incident 관리</h2><p>탐지부터 인지·완화·복구·종료까지 감사 가능한 상태 전이를 관리합니다.</p></div><button class="ghost" @click="load"><CpfIcon name="refresh"/> 새로고침</button></div><section class="cpf-card"><div class="cpf-card-head"><h2>Incident 등록</h2></div><div class="cpf-form-grid"><label>심각도<select v-model="form.severity"><option>SEV1</option><option>SEV2</option><option>SEV3</option><option>SEV4</option></select></label><label class="span-2">제목<input v-model="form.title" placeholder="장애 상황을 한 문장으로 입력"></label><label class="span-2">요약<textarea v-model="form.summary" rows="2"></textarea></label><button class="primary" :disabled="busy" @click="create">Incident 생성</button></div></section><section class="cpf-card"><div class="cpf-card-head"><h2>현재 Incident</h2></div><p v-if="error" class="error-banner">{{error}}</p><div class="table-wrap"><table><thead><tr><th>ID</th><th>Severity</th><th>제목</th><th>상태</th><th>발생</th><th>조치</th></tr></thead><tbody><tr v-for="r in rows" :key="String(r.incidentId)"><td>{{r.incidentNo||r.incidentId}}</td><td><span class="cpf-status" :class="String(r.severity).includes('1')?'danger':'warning'">{{r.severity}}</span></td><td>{{r.title}}</td><td>{{r.status}}</td><td>{{r.detectedAt}}</td><td><div class="cpf-toolbar"><button class="ghost small" @click="transition(r,'ACKNOWLEDGED')">인지</button><button class="ghost small" @click="transition(r,'MITIGATED')">완화</button><button class="primary small" @click="transition(r,'RESOLVED')">복구</button></div></td></tr></tbody></table></div></section></div></template>